ALTER TABLE public.club_bar_settings DROP CONSTRAINT club_bar_settings_staff_payday_check;
ALTER TABLE public.club_bar_settings ADD CONSTRAINT club_bar_settings_staff_payday_check CHECK (staff_payday IS NULL OR staff_payday BETWEEN 1 AND 31);

CREATE OR REPLACE FUNCTION public.bar_set_staff_payday(_club_id uuid, _day integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT coalesce((public.is_club_admin_or_permitted(auth.uid(),_club_id,'bar') OR public.has_club_permission(auth.uid(),_club_id,'finance') OR public.has_role(auth.uid(),'admin')),false) THEN RAISE EXCEPTION 'Bar or finance permission required'; END IF; IF _day IS NOT NULL AND (_day<1 OR _day>31) THEN RAISE EXCEPTION 'Pay day must be between 1 and 31'; END IF; INSERT INTO club_bar_settings(club_id) VALUES(_club_id) ON CONFLICT(club_id) DO NOTHING; UPDATE club_bar_settings SET staff_payday=_day,updated_at=now() WHERE club_id=_club_id; END $$;

CREATE OR REPLACE FUNCTION public._bar_prepare_payroll_runs() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s record;r uuid;v_today date;v_period date;v_last_day integer;made integer:=0; BEGIN v_today:=(now() AT TIME ZONE 'Africa/Johannesburg')::date; v_period:=date_trunc('month',v_today)::date; v_last_day:=extract(day FROM (date_trunc('month',v_today)::date + interval '1 month' - interval '1 day'))::integer; FOR s IN SELECT cbs.club_id, cbs.staff_payday FROM club_bar_settings cbs WHERE cbs.staff_payday IS NOT NULL AND extract(day FROM v_today)=least(cbs.staff_payday,v_last_day) LOOP IF EXISTS(SELECT 1 FROM bar_payroll_runs bpr WHERE bpr.club_id=s.club_id AND bpr.period=v_period) THEN CONTINUE; END IF; INSERT INTO bar_payroll_runs(club_id,period) VALUES(s.club_id,v_period) ON CONFLICT(club_id,period) DO NOTHING RETURNING id INTO r; IF r IS NULL THEN CONTINUE; END IF; INSERT INTO bar_payroll_run_lines(run_id,club_id,staff_id,staff_name,salary,tips) SELECT r,d.club_id,d.id,d.label,coalesce(sal.monthly_salary,0),greatest(coalesce(t.a,0)-coalesce(p.a,0),0) FROM bar_counter_devices d LEFT JOIN bar_staff_salaries sal ON sal.club_id=d.club_id AND sal.staff_id=d.id LEFT JOIN(SELECT bt.staff_id,sum(bt.amount) a FROM bar_tips bt WHERE bt.club_id=s.club_id AND bt.status='earned' GROUP BY bt.staff_id)t ON t.staff_id=d.id LEFT JOIN(SELECT bp.staff_id,sum(bp.amount) a FROM bar_tip_payouts bp WHERE bp.club_id=s.club_id GROUP BY bp.staff_id)p ON p.staff_id=d.id WHERE d.club_id=s.club_id AND d.active AND nullif(btrim(d.label),'') IS NOT NULL AND (coalesce(sal.monthly_salary,0)>0 OR coalesce(t.a,0)-coalesce(p.a,0)>0); made:=made+1; END LOOP; RETURN made; END $$;